"""Print a course project's lessons, tasks and files as a tree, so you can check its structure.

Run it from the course project's top folder:   python show_course.py
or give the folder:                             python show_course.py path/to/course
"""

import sys
from pathlib import Path

SKIP = {".idea", "__pycache__", ".git", ".venv", "venv", "build", "out", ".gradle"}


def show(folder: Path, depth: int = 0) -> None:
    entries = sorted(folder.iterdir(), key=lambda p: (p.is_file(), p.name.lower()))
    for entry in entries:
        if entry.name in SKIP or entry.name.startswith(".") or entry.name == Path(__file__).name:
            continue
        if entry.is_dir():
            print("  " * depth + entry.name + "/")
            show(entry, depth + 1)
        elif entry.suffix != ".pyc":
            print("  " * depth + entry.name)


if __name__ == "__main__":
    root = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.cwd()
    print(root.resolve().name + "/")
    show(root, 1)

